def min_stack_ops(ops):
    stack = []
    out = []
    for op in ops:
        if op[0] == 'push':
            x = op[1]
            stack.append((x, min(x, stack[-1][1]) if stack else x))
        elif op[0] == 'pop':
            stack.pop()
        elif op[0] == 'top':
            out.append(stack[-1][0])
        else:
            out.append(stack[-1][1])
    return out
